import{F as PN,I as Pi,R as Qa,X as Vt,Yt as qM,Z as WE,dt as bT,hn as yc,kt as h,rt as Zf,t as $f,tt as YM}from"./chunk-ZZ9HoQbQ.js";import{t as f}from"./chunk-DjcAgKLN.js";import{t as b}from"./chunk-D1SZbloK.js";import{t as T}from"./chunk-WJN__D8s.js";function x(a,o){a&1&&(Qa(0,`mci-section`,2)(1,`p`),PN(2,`La diocesi di Augusta, in latino `),Qa(3,`em`,4),PN(4,`Dioecesis Augustana Vindelicorum`),Zf(),PN(5,`, è una sede della Chiesa cattolica suffraganea dell’arcidiocesi di Monaco e Frisinga. Comprende la Baviera sud-occidentale e ha sede nella città di Augusta, dove si trova la cattedrale di Santa Maria.`),Zf(),Qa(6,`p`),PN(7,`La pagina di riferimento riporta 1.285.479 battezzati su 2.417.146 abitanti, 36 decanati e 1.001 parrocchie, e indica come vescovo il dott. Bertram Meyer. Questi dati e la grafia del nome sono ripresi dalla fonte e non costituiscono un quadro statistico aggiornato.`),Zf(),Qa(8,`h3`),PN(9,`Dalle origini all’età medievale`),Zf(),Qa(10,`p`),PN(11,`Augusta Vindelicorum era l’antico nome della città, appartenente alla provincia imperiale della `),Qa(12,`em`,4),PN(13,`Raetia secunda`),Zf(),PN(14,` dalla conquista romana fino alla fine dell’Impero. Il racconto storico della fonte collega le origini della comunità cristiana a sant’Afra e Dionigi, attorno al II secolo, e cita scoperte archeologiche che sembrano sostenere una continuità della successione episcopale anche durante le invasioni barbariche.`),Zf(),Qa(15,`p`),PN(16,`Sotto il vescovo Simperto, nell’VIII secolo, Augusta divenne un importante centro della cultura benedettina. Questo sviluppo favorì la fondazione di abbazie come Wessobrunn e Ottobeuren. La diocesi incorporò inoltre i territori della soppressa diocesi di Neuburg.`),Zf(),Qa(17,`p`),PN(18,`Secondo la ricostruzione riportata nella fonte, il vescovato acquisì il potere temporale verso la fine dell’VIII secolo. Con sant’Ulrico consolidò poi il proprio ruolo sia ecclesiastico sia territoriale.`),Zf(),Qa(19,`h3`),PN(20,`La Dieta di Augusta e il rinnovamento cattolico`),Zf(),Qa(21,`p`),PN(22,`Nel 1530 la città ospitò la Dieta di Augusta, il parlamento dell’Impero. La fonte la presenta come l’occasione in cui la Chiesa cattolica e quella evangelica furono per la prima volta presenti insieme.`),Zf(),Qa(23,`p`),PN(24,`Nel 1549 il vescovo Otto Truchsess von Waldburg fondò un’università cattolica riformata a Dillingen, con l’aiuto del gesuita Pietro Canisio, indicato nel testo originale come vescovo di Vienna. L’università contribuì alla diffusione degli ideali del Concilio di Trento nella diocesi.`),Zf(),Qa(25,`h3`),PN(26,`L’arte barocca e i cambiamenti dell’Ottocento`),Zf(),Qa(27,`p`),PN(28,`Durante il periodo barocco, architetti, pittori e stuccatori arricchirono le chiese della diocesi di numerose opere d’arte. A questa stagione appartengono celebri monasteri e chiese parrocchiali dell’area del Pfaffenwinkel.`),Zf(),Qa(29,`p`),PN(30,`Il testo ricorda la scuola di Wessobrunn, il Marienmünster presso Dießen, i monasteri di Benediktbeuern e di sant’Ottilio presso Wallfahrtskirchen e la Wieskirche di Steingaden.`),Zf(),Qa(31,`p`),PN(32,`All’inizio del XIX secolo, con la secolarizzazione e la fine del Sacro Romano Impero, il vescovato perse il potere temporale. Il 1° aprile 1818 la diocesi si ampliò includendo il territorio della soppressa diocesi di Costanza, secondo quanto riportato nella fonte.`),Zf()())}function z(a,o){a&1&&(Qa(0,`mci-section`,3)(1,`p`),PN(2,`La storia della Missione Cattolica Italiana di Augsburg è legata a quella degli italiani che hanno scelto Augusta e la sua diocesi come luogo di lavoro e di vita. Dalle prime celebrazioni in lingua italiana alla nascita di una comunità stabile, il suo cammino intreccia fede, accoglienza e impegno sociale.`),Zf(),Qa(3,`h3`),PN(4,`Le origini: una presenza italiana prima della Missione`),Zf(),Qa(5,`p`),PN(6,`Già prima della Seconda guerra mondiale, il capoluogo della Svevia era una meta per commercianti italiani e persone in cerca di occupazione. Per circa quarant’anni, padre P. Glogger, dell’abbazia benedettina locale, si dedicò alla loro cura pastorale. Anche in seguito fu ricordato come «padre, consigliere e amico degli italiani».`),Zf(),Qa(7,`p`),PN(8,`Nel 1951 aprì una missione a Monaco. Il suo missionario, padre Julius Valentinelli, poté così assicurare agli italiani di Augusta una Messa mensile nella chiesa di St. Georg. Il successore, don E. Borgialli, mantenne questo appuntamento fino all’arrivo di un sacerdote residente ad Augsburg.`),Zf(),Qa(9,`h3`),PN(10,`1961–1962: l’arrivo di don Cazzetta`),Zf(),Qa(11,`p`),PN(12,`Nell’agosto 1961 don A. Cazzetta giunse da Hildesheim per occuparsi degli italiani della città e della diocesi. In una lettera al direttore delle missioni, padre Zanatta, raccontò di aver trovato alloggio nella Casa di St. Ulrich, in Caritasweg 10. Le autorità ecclesiastiche lo avevano accolto con favore, promettendo di creare presto un centro per gli italiani.`),Zf(),Qa(13,`p`),PN(14,`Con decreto della Curia del 1° agosto 1961, fu nominato curato degli italiani a partire dal 1° ottobre. Durante il suo breve soggiorno aprì un ufficio in Moritz-Platz 5 e organizzò celebrazioni regolari. Non riuscì, invece, a trovare un altro sacerdote dall’Italia e un assistente sociale per la comunità.`),Zf(),Qa(15,`p`),PN(16,`Nel novembre dello stesso anno fu chiamato dal presidente delle federazioni della Caritas tedesca a svolgere il ruolo di consigliere presso la sede centrale di Friburgo. La Missione rimase senza titolare nel dicembre 1961 e nel gennaio 1962, tornando a una situazione di precarietà.`),Zf(),Qa(17,`p`),PN(18,`In quei mesi monsignor Schönmetzler, parroco di St. Georg, continuò a riunire gli italiani per la Messa. A Dillingen, Lauingen e nei paesi vicini celebrava per loro anche J. Stimpfle, allora rettore del seminario e futuro vescovo di Augsburg.`),Zf(),Qa(19,`h3`),PN(20,`1962–1966: don Zorzi e una comunità diffusa`),Zf(),Qa(21,`p`),PN(22,`Il 5 febbraio 1962 arrivò don G. Zorzi, già cappellano della missione di Francoforte. Secondo una statistica del 1961, nella diocesi vivevano circa 9.000 italiani, distribuiti su un territorio molto ampio.`),Zf(),Qa(23,`p`),PN(24,`Don Zorzi celebrava due volte al mese nella cappella delle confessioni di St. Georg e una volta al mese a Kempten, Bobingen, Kaufbeuren e Illertissen. Secondo le necessità raggiungeva anche Friedberg, Lindau, Lindenberg, Vöhringen e Preißenberg.`),Zf(),Qa(25,`p`),PN(26,`Nei rapporti alla Curia e alla direzione delle missioni di Colonia descrisse le difficoltà del suo incarico: le lunghe trattative con i parroci tedeschi per ottenere una chiesa, i problemi socioculturali degli italiani e, soprattutto, la mancanza di un centro ad Augsburg. Nel luglio 1964 la Missione ottenne una sede più spaziosa in Theresienstraße 12 – Ulrichsplatz.`),Zf(),Qa(27,`p`),PN(28,`Pastore molto attivo, don Zorzi portò con sé anche l’esperienza maturata al `),Qa(29,`em`),PN(30,`Corriere d’Italia`),Zf(),PN(31,` di Francoforte. Si interessò ai mezzi di comunicazione e realizzò diverse trasmissioni radiofoniche su temi di interesse generale.`),Zf(),Qa(32,`h3`),PN(33,`1966–1972: don Fraschini e lo sviluppo della Missione`),Zf(),Qa(34,`p`),PN(35,`Il 1° febbraio 1966 don M. Fraschini arrivò come cappellano di don Zorzi. Dopo sole due settimane gli fu affidata la nuova missione di Kempten, con 18 decanati e circa 6.000 italiani nella regione dell’Algovia.`),Zf(),Qa(36,`p`),PN(37,`Il 1° settembre 1966 don Zorzi si trasferì a Francoforte per dirigere il `),Qa(38,`em`),PN(39,`Corriere d’Italia`),Zf(),PN(40,`. Don Fraschini gli succedette ad Augsburg, assumendo la cura di circa 18.000 italiani sparsi nella diocesi. Affrontò questo compito con grande iniziativa: ottenne, con decreto diocesano del 1° gennaio 1967, l’erezione della «Missione cum cura animarum» e organizzò attività pastorali e sociali in circa trenta città, con particolare attenzione all’Algovia.`),Zf(),Qa(41,`p`),PN(42,`Il suo impegno comprendeva numerose attività:`),Zf(),Qa(43,`ul`)(44,`li`),PN(45,`Preparazione alla Prima Comunione e alla Cresima in diverse località.`),Zf(),Qa(46,`li`),PN(47,`Messa annuale con il vescovo J. Stimpfle presso l’Englisches Institut.`),Zf(),Qa(48,`li`),PN(49,`Da tre a cinque Messe nel fine settimana, seguite dalla proiezione di un film.`),Zf(),Qa(50,`li`),PN(51,`Accompagnamento del gruppo ACLI e dei giovani del G.E.I., incontri con i genitori e lezioni di religione nelle scuole. `),Zf(),Qa(52,`li`),PN(53,`Visite agli ammalati e ai detenuti.`),Zf(),Qa(54,`li`),PN(55,`Celebrazioni pasquali in 31 località nel 1967 e feste di Natale per i bambini in 15 località nel 1968.`),Zf()(),Qa(56,`p`),PN(57,`Si definiva un «missionario tuttofare», sempre a disposizione dei connazionali. L’arrivo di don Pittarello come cappellano nel 1967 e la sua nomina a missionario di Kempten nel 1969 alleggerirono il lavoro. Nel 1972 la diocesi istituì una terza missione italiana indipendente per i 3.600 italiani di Neu-Ulm e dintorni. Don Fraschini poté così concentrarsi sui circa 3.500 italiani di Augusta.`),Zf(),Qa(58,`h3`),PN(59,`1979–1987: la Domus Latina e il venticinquesimo anniversario`),Zf(),Qa(60,`p`),PN(61,`Le attività richiedevano spazi adeguati, ma i locali di Theresienstraße 12 e Ulrichsplatz 13 non erano più sufficienti. Il 23 giugno 1979 il vescovo J. Stimpfle inaugurò ufficialmente la `),Qa(62,`strong`),PN(63,`Domus Latina`),Zf(),PN(64,`, in Alte Gasse 15. La Missione italiana trovò finalmente la sede tanto desiderata, insieme alle missioni spagnola e portoghese.`),Zf(),Qa(65,`p`),PN(66,`Nel 1987 don Fraschini celebrò il venticinquesimo anniversario della Missione con un anno di iniziative religiose e sociali. Il motto scelto esprimeva il senso di quel cammino nella Chiesa di Augusta: «una comunità del popolo di Dio migrante».`),Zf(),Qa(67,`h3`),PN(68,`1993–2012: don Gozio, integrazione e dialogo`),Zf(),Qa(69,`p`),PN(70,`Il 28 febbraio 1993 il vescovo Viktor J. Dammertz OSB salutò don Fraschini, che si ritirava in pensione dopo 27 anni di attività. Il 1° marzo gli succedette don A. Gozio, alla guida di una comunità di circa 7.500 italiani, metà dei quali residenti ad Augsburg.`),Zf(),Qa(71,`p`),PN(72,`Don Gozio dedicò particolare attenzione ai giovani e alla loro integrazione sociale e religiosa. La Missione collaborava strettamente con le parrocchie tedesche per i sacramenti e la catechesi. Alle attività tradizionali si affiancarono pellegrinaggi in Italia e in Germania e incontri pomeridiani per gli anziani.`),Zf(),Qa(73,`p`),PN(74,`La comunità era maturata e le sue esigenze stavano cambiando. I numerosi matrimoni tra italiani e tedeschi rendevano sempre più sentito il desiderio di uno scambio culturale. Nacquero così iniziative con la società DIKA, dedicata allo scambio culturale italo-tedesco, per conoscere e approfondire la lingua e la cultura dei due Paesi.`),Zf(),Qa(75,`p`),PN(76,`Don Gozio guidò la Missione per 19 anni, fino alla morte nel maggio 2012. Il `),Qa(77,`strong`),PN(78,`1° luglio 2012`),Zf(),PN(79,` padre Bruno Zuchowski divenne il nuovo missionario.`),Zf()())}var S=class a{route=h(Vt);routeData=T(this.route.data,{initialValue:this.route.snapshot.data});isDiocese=Pi(()=>this.routeData().isDiocese===!0);links=[{label:`La Missione`,path:`/history/mission`},{label:`La diocesi`,path:`/history/diocese`}];static ɵfac=function(n){return new(n||a)};static ɵcmp=$f({type:a,selectors:[[`mci-history`]],decls:4,vars:2,consts:[[`imageUrl`,`https://images.pexels.com/photos/7219090/pexels-photo-7219090.jpeg`,`title`,`Storia`,3,`links`],[1,`height-container`],[`title`,`La diocesi di Augsburg`,`backgroundColor`,`var(--mat-sys-surface)`,`textColor`,`var(--mat-sys-on-surface)`],[`title`,`La storia della Missione`,`backgroundColor`,`var(--mat-sys-surface)`,`textColor`,`var(--mat-sys-on-surface)`],[`lang`,`la`]],template:function(n,l){n&1&&(yc(0,`mci-hero`,0),Qa(1,`div`,1),qM(2,x,33,0,`mci-section`,2)(3,z,80,0,`mci-section`,3),Zf()),n&2&&(WE(`links`,l.links),bT(2),YM(l.isDiocese()?2:3))},dependencies:[b,f],styles:[`[_nghost-%COMP%]   h3[_ngcontent-%COMP%]{margin-block:48px 24px;font-size:clamp(26px,4vw,38px)}[_nghost-%COMP%]   li[_ngcontent-%COMP%] + li[_ngcontent-%COMP%]{margin-top:12px}[_nghost-%COMP%]   .source-note[_ngcontent-%COMP%]{margin-top:48px;font-size:16px}[_nghost-%COMP%]   .source-note[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]{color:inherit;text-underline-offset:3px}[_nghost-%COMP%]   .source-note[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:focus-visible{outline:2px solid currentColor;outline-offset:4px}`]})};export{S as HistoryComponent};